package com.comfymobile.app;

import org.json.*;
import java.io.*;
import java.security.SecureRandom;
import java.util.*;

/** No Activity or WebView dependency: the same state machine survives UI destruction. */
final class BatchEngine {
 interface Transport {
  JSONObject get(JSONObject job,String path)throws Exception;
  JSONObject post(JSONObject job,String path,JSONObject body)throws Exception;
  String upload(JSONObject job,JSONObject file)throws Exception;
  JSONObject cache(JSONObject job,String path,String id)throws Exception;
 }
 final BatchStore store;final Transport net;final JSONObject workflows;private final SecureRandom random=new SecureRandom();
 BatchEngine(BatchStore store,Transport net,JSONObject workflows){this.store=store;this.net=net;this.workflows=workflows;}
 private boolean flag(String m,String flag)throws Exception{return store.job(m).getJSONObject("batch").optBoolean(flag);}
 private void task(JSONObject j,String state,String stage)throws Exception{j.put("task",state).put("stage",stage);store.save(j);}
 void tick(String mode)throws Exception{JSONObject j=store.job(mode);if(j==null||BatchStore.terminal(j.optString("task"))||System.currentTimeMillis()<j.optLong("retryAt"))return;try{advance(j);j=store.job(mode);if(j!=null&&j.optInt("networkFailures")>0){j.put("networkFailures",0).put("retryAt",0);store.save(j);}}catch(IOException e){j=store.job(mode);int failures=j.optInt("networkFailures")+1;j.put("networkFailures",failures).put("retryAt",System.currentTimeMillis()+Math.min(30000,2000L*(1L<<Math.min(4,failures-1))));j.put("stage","连接中断，正在自动重试；批次保留");store.save(j);}catch(Exception e){j=store.job(mode);String message=e.getMessage()==null?e.toString():e.getMessage();String lower=message.toLowerCase(Locale.ROOT);String code=lower.contains("vbar allocation failed")?"vbar":lower.contains("out of memory")||lower.contains("outofmemory")||lower.contains("cuda error: memory")?"oom":"";j.put("errorCode",code).put("errorDetails",message);String summary=errorSummary(message);j.put("error",code.equals("vbar")?"电脑动态显存分配失败。请在电脑启动参数中加入 --disable-dynamic-vram，重启 ComfyUI 后重试。":code.equals("oom")?"电脑显存不足，请降低图改图缩放比例或文生图尺寸后重试。\n"+summary:summary);task(j,"error","任务失败，已保留完成的图片");}}
 static String errorSummary(String message){String text=message;try{JSONArray events=new JSONArray(message);for(int i=events.length()-1;i>=0;i--){JSONArray event=events.optJSONArray(i);if(event==null||!"execution_error".equals(event.optString(0)))continue;JSONObject data=event.optJSONObject(1);if(data!=null){text="节点 "+data.optString("node_id")+"（"+data.optString("node_type")+"）："+data.optString("exception_type")+" · "+data.optString("exception_message");break;}}}catch(JSONException ignored){}text=text.trim();return text.length()>600?text.substring(0,600)+"…":text;}
 private void advance(JSONObject j)throws Exception{String mode=j.getString("mode");JSONObject b=j.getJSONObject("batch");
  if(j.optBoolean("remoteOwned")){remotePoll(j);return;}
  if(j.optBoolean("submissionUncertain")){String recovered=recover(j);if(recovered!=null){j.put("promptId",recovered).put("submissionUncertain",false);store.save(j);}else{int misses=j.optInt("recoveryMisses")+1;j.put("recoveryMisses",misses);if(misses<3){j.put("retryAt",System.currentTimeMillis()+3000);store.save(j);return;}j.put("submissionUncertain",false).put("recoveryMisses",0);store.save(j);}}
  if(flag(mode,"cancelRequested")){cancel(j);return;}
  if(j.optString("promptId").isEmpty()){
   if(b.getInt("completed")>=b.getInt("total")){task(j,"done","本批次已完成");return;}
   if(flag(mode,"pauseRequested")){task(j,"paused","已暂停，可继续本批次");return;}
   for(int n=1;n<=2;n++){String key="upload"+n;if(j.has(key)&&!b.has("image"+n)){task(j,"uploading","正在上传第 "+n+" 张输入图片");String uploaded=net.upload(j,j.getJSONObject(key));b.put("image"+n,uploaded);store.save(j);if(flag(mode,"cancelRequested")||flag(mode,"pauseRequested"))return;}}
   submit(j);return;
  }
  String pid=j.getString("promptId");JSONObject h=net.get(j,"/history/"+pid).optJSONObject(pid);
  if(h!=null){JSONObject status=h.optJSONObject("status");if(status!=null&&"error".equals(status.optString("status_str")))throw new Exception(status.optJSONArray("messages")==null?"电脑执行失败":status.getJSONArray("messages").toString());if(status!=null&&status.optBoolean("completed")){collect(j,h);j.remove("promptId");j.put("progress",JSONObject.NULL);if(flag(mode,"cancelRequested"))task(j,"cancelled","已取消整个批次剩余任务");else if(b.getInt("completed")>=b.getInt("total"))task(j,"done","本批次已完成");else if(flag(mode,"pauseRequested"))task(j,"paused","已暂停，可继续本批次");else task(j,"between","准备下一张");return;}}
  JSONObject q=net.get(j,"/queue");boolean running=contains(q.optJSONArray("queue_running"),pid),pending=contains(q.optJSONArray("queue_pending"),pid);if(running||pending){j.put("missing",0);task(j,running?"running":"queued",(flag(mode,"pauseRequested")?"暂停待生效 · 当前图片完成后暂停":"第 "+(b.getInt("completed")+1)+" / "+b.getInt("total")+" 张 · "+(running?"电脑运行中":"等待电脑执行")));}else{int missing=j.optInt("missing")+1;j.put("missing",missing);if(missing>=5)throw new Exception("电脑队列及历史中未找到当前任务，请检查电脑是否重启或手动清除了记录。");store.save(j);}
 }
 private static boolean contains(JSONArray a,String pid)throws Exception{if(a!=null)for(int i=0;i<a.length();i++)if(pid.equals(a.getJSONArray(i).optString(1)))return true;return false;}
 private void submit(JSONObject j)throws Exception{JSONObject b=j.getJSONObject("batch"),params=b.getJSONObject("params");String seed=b.optBoolean("random")?Long.toString(random.nextInt()&0xffffffffL):params.getString("seed");b.put("currentSeed",seed);j.put("seed",seed);JSONObject w=new JSONObject(workflows.getJSONObject(j.getString("workflow")).toString()),p=w.getJSONObject("prompt");p.getJSONObject(w.getString("positive")).getJSONObject("inputs").put(w.getString("textField"),params.getString("positive"));p.getJSONObject(w.getString("negative")).getJSONObject("inputs").put(w.optString("negativeField",w.getString("textField")),params.optString("negative"));p.getJSONObject(w.getString("seed")).getJSONObject("inputs").put(w.getString("seedField"),Long.parseLong(seed));if(!j.getString("mode").equals("image")){p.getJSONObject(w.getString("size")).getJSONObject("inputs").put("width",params.getInt("width")).put("height",params.getInt("height"));}else{p.getJSONObject("mobile_width").getJSONObject("inputs").put("values.b",params.optDouble("scale",1));p.getJSONObject("mobile_height").getJSONObject("inputs").put("values.b",params.optDouble("scale",1));p.getJSONObject("72").getJSONObject("inputs").put("image",b.getString("image1"));if(j.getString("workflow").equals("dual"))p.getJSONObject("90").getJSONObject("inputs").put("image",b.getString("image2"));}if(j.getString("workflow").equals("anima")){String variant=params.optString("animaModel","base");JSONObject model=w.getJSONObject("models").optJSONObject(variant);if(model==null)throw new Exception("请选择 base 或 turbo 模型");String artist=params.optString("artistOption",w.getString("defaultArtist"));p.getJSONObject(w.getString("modelNode")).getJSONObject("inputs").put("unet_name",model.getString("file"));p.getJSONObject(w.getString("samplerNode")).getJSONObject("inputs").put("steps",model.getInt("steps")).put("cfg",model.getDouble("cfg"));p.getJSONObject(w.getString("artistNode")).getJSONObject("inputs").put("artist",artist);params.put("animaModel",variant).put("artistOption",artist).put("steps",model.getInt("steps")).put("cfg",model.getDouble("cfg"));}j.put("output",w.getString("output"));
  if(flag(j.getString("mode"),"cancelRequested")||flag(j.getString("mode"),"pauseRequested"))return;
  if(j.optBoolean("remotePreferred")){JSONObject meta=new JSONObject().put("mode",j.getString("mode")).put("workflow",j.getString("workflow")).put("batch_id",b.getString("id")).put("batch_index",b.getInt("completed")+1).put("batch_total",b.getInt("total")).put("seed",seed);JSONObject template=new JSONObject().put("prompt",p).put("client_id",j.getString("clientId")+"-background").put("extra_data",new JSONObject().put("extra_pnginfo",new JSONObject().put("comfy_mobile",meta)));JSONObject plan=new JSONObject().put("id",b.getString("id")).put("owner",j.getString("clientId")).put("total",b.getInt("total")).put("completed",b.getInt("completed")).put("template",template).put("seed_node",w.getString("seed")).put("seed_field",w.getString("seedField")).put("random",b.optBoolean("random")).put("seed",params.getString("seed")).put("current_seed",seed).put("output",w.getString("output")).put("workflow",j.getString("workflow")).put("mobile_inputs",new JSONObject(params.toString()).put("image1",b.optString("image1")).put("image2",b.optString("image2")));j.put("remoteOwned",true).put("remoteAttached",false).put("remotePlan",plan).put("remoteCollected",b.getInt("completed"));task(j,"submitting","正在把整批任务交给电脑");remotePoll(j);return;}
  // Persist intent before POST. A restart searches the server before considering a retry.
  j.put("submissionUncertain",true).put("recoveryMisses",0);task(j,"submitting","正在提交第 "+(b.getInt("completed")+1)+" 张");JSONObject meta=new JSONObject().put("mode",j.getString("mode")).put("workflow",j.getString("workflow")).put("batch_id",b.getString("id")).put("batch_index",b.getInt("completed")+1).put("batch_total",b.getInt("total")).put("seed",seed);JSONObject result=net.post(j,"/prompt",new JSONObject().put("prompt",p).put("client_id",j.getString("clientId")+"-background").put("extra_data",new JSONObject().put("extra_pnginfo",new JSONObject().put("comfy_mobile",meta))));
  j.put("promptId",result.getString("prompt_id")).put("submissionUncertain",false).put("missing",0).put("progress",JSONObject.NULL);task(j,"queued","任务已提交");
 }
 private boolean matching(JSONObject j,JSONArray prompt)throws Exception{if(prompt==null)return false;JSONObject extra=prompt.optJSONObject(3),png=extra==null?null:extra.optJSONObject("extra_pnginfo"),meta=png==null?null:png.optJSONObject("comfy_mobile");return meta!=null&&j.getJSONObject("batch").getString("id").equals(meta.optString("batch_id"))&&j.getJSONObject("batch").getInt("completed")+1==meta.optInt("batch_index");}
 private String recover(JSONObject j)throws Exception{JSONObject q=net.get(j,"/queue");for(String key:new String[]{"queue_running","queue_pending"}){JSONArray a=q.optJSONArray(key);if(a!=null)for(int i=0;i<a.length();i++){JSONArray prompt=a.getJSONArray(i);if(matching(j,prompt))return prompt.getString(1);}}JSONObject history=net.get(j,"/history?max_items=200");Iterator<String> keys=history.keys();while(keys.hasNext()){String pid=keys.next();if(matching(j,history.getJSONObject(pid).optJSONArray("prompt")))return pid;}return null;}
 private void collect(JSONObject j,JSONObject h)throws Exception{JSONObject b=j.getJSONObject("batch"),params=b.getJSONObject("params"),outputs=h.optJSONObject("outputs"),output=outputs==null?null:outputs.optJSONObject(j.getString("output"));JSONArray images=output==null?null:output.optJSONArray("images");if(images==null||images.length()==0)throw new Exception("任务结束但没有输出图片");String pid=j.getString("promptId");task(j,"downloading","正在保存第 "+(b.getInt("completed")+1)+" 张");for(int i=0;i<images.length();i++){JSONObject image=images.getJSONObject(i);String key=j.getString("server")+"|"+pid+"|"+image.optString("subfolder")+"|"+image.getString("filename");JSONObject item=store.imageForKey(key);if(item==null){String id=UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8))+".png";String path="/view?filename="+encode(image.getString("filename"))+"&subfolder="+encode(image.optString("subfolder"))+"&type="+encode(image.optString("type","output"));item=net.cache(j,path,id);item.put("key",key).put("mode",j.getString("mode")).put("workflow",j.getString("workflow")).put("created",System.currentTimeMillis()).put("seed",b.getString("currentSeed")).put("prompt",params.getString("positive")).put("negative",params.optString("negative")).put("promptId",pid).put("batchId",b.getString("id")).put("batchIndex",b.getInt("completed")+1).put("batchTotal",b.getInt("total"));for(String field:new String[]{"scale","sourceWidth","sourceHeight","animaModel","artistOption","steps","cfg","translationModel"})if(params.has(field))item.put(field,params.get(field));store.image(item);}JSONArray saved=j.getJSONArray("images");boolean exists=false;for(int n=0;n<saved.length();n++)if(saved.getJSONObject(n).getString("key").equals(key))exists=true;if(!exists)saved.put(item);store.save(j);}if(!pid.equals(b.optString("lastCompleted"))){b.put("completed",b.getInt("completed")+1).put("lastCompleted",pid);}store.save(j);}
 private static String encode(String value)throws Exception{return java.net.URLEncoder.encode(value,"UTF-8");}
 private void remotePoll(JSONObject j)throws Exception{JSONObject b=j.getJSONObject("batch");String mode=j.getString("mode"),id=b.getString("id"),path="/comfy-mobile/batches/"+id;if(!j.optBoolean("remoteAttached")){if(j.getJSONObject("remotePlan").has("mobile_inputs")&&!net.get(j,"/comfy-mobile/capabilities").optBoolean("desktop_workflows"))throw new Exception("请重启 ComfyUI，启用电脑最新工作流参数同步");net.post(j,"/comfy-mobile/batches",j.getJSONObject("remotePlan"));j.put("remoteAttached",true);store.save(j);}JSONObject latest=store.job(mode).getJSONObject("batch");int version=latest.optInt("controlVersion");if(version>j.optInt("remoteSentVersion")){String command=latest.optBoolean("cancelRequested")?"cancel":latest.optBoolean("pauseRequested")?"pause":"resume";net.post(j,path+"/control",new JSONObject().put("owner",j.getString("clientId")).put("version",version).put("command",command));j.put("remoteSentVersion",version);store.save(j);}JSONObject remote=net.get(j,path+"?owner="+encode(j.getString("clientId")));JSONObject effective=remote.optJSONObject("effective_settings");if(effective!=null){java.util.Iterator<String> keys=effective.keys();while(keys.hasNext()){String key=keys.next();b.getJSONObject("params").put(key,effective.get(key));}}b.put("completed",remote.getInt("completed"));String pid=remote.optString("prompt_id","");if(remote.isNull("prompt_id"))pid="";if(!pid.equals(j.optString("promptId")))j.put("progress",JSONObject.NULL);if(pid.isEmpty())j.remove("promptId");else j.put("promptId",pid);if(!remote.isNull("current_seed")){b.put("currentSeed",remote.getString("current_seed"));j.put("seed",remote.getString("current_seed"));}
  JSONArray outputs=remote.getJSONArray("outputs");for(int n=0;n<outputs.length();n++){JSONObject record=outputs.getJSONObject(n);if(record.getInt("index")<=j.optInt("remoteCollected"))continue;task(j,"downloading","正在接收电脑完成的第 "+record.getInt("index")+" 张");JSONArray images=record.getJSONArray("images");for(int i=0;i<images.length();i++){JSONObject image=images.getJSONObject(i);String key=j.getString("server")+"|"+record.getString("prompt_id")+"|"+image.optString("subfolder")+"|"+image.getString("filename");JSONObject item=store.imageForKey(key);if(item==null){String localId=UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8))+".png";item=net.cache(j,"/view?filename="+encode(image.getString("filename"))+"&subfolder="+encode(image.optString("subfolder"))+"&type="+encode(image.optString("type","output")),localId);JSONObject params=b.getJSONObject("params");item.put("key",key).put("mode",mode).put("workflow",j.getString("workflow")).put("created",System.currentTimeMillis()).put("seed",record.getString("seed")).put("prompt",params.getString("positive")).put("negative",params.optString("negative")).put("promptId",record.getString("prompt_id")).put("batchId",id).put("batchIndex",record.getInt("index")).put("batchTotal",b.getInt("total"));for(String field:new String[]{"scale","sourceWidth","sourceHeight","animaModel","artistOption","steps","cfg","translationModel"})if(params.has(field))item.put(field,params.get(field));store.image(item);}boolean found=false;JSONArray saved=j.getJSONArray("images");for(int s=0;s<saved.length();s++)if(saved.getJSONObject(s).getString("id").equals(item.getString("id")))found=true;if(!found)saved.put(item);store.save(j);}j.put("remoteCollected",record.getInt("index"));store.save(j);}
  if(remote.isNull("current_seed")&&outputs.length()>0){String lastSeed=outputs.getJSONObject(outputs.length()-1).getString("seed");b.put("currentSeed",lastSeed);j.put("seed",lastSeed);}String state=remote.getString("state");if(state.equals("error"))throw new Exception(remote.optString("error","电脑执行失败"));if(remote.optString("desired").equals("pause")&&!state.equals("paused"))j.put("stage","当前图片完成后暂停");else j.put("stage",state.equals("paused")?"已暂停，可继续本批次":state.equals("done")?"本批次已完成":state.equals("cancelled")?"已取消整个批次剩余任务":"电脑持续运行中 · "+b.getInt("completed")+" / "+b.getInt("total"));j.put("task",state);store.save(j);
 }
 private void cancel(JSONObject j)throws Exception{String pid=j.optString("promptId");if(pid.isEmpty()){task(j,"cancelled","已取消整个批次剩余任务");return;}JSONObject h=net.get(j,"/history/"+pid).optJSONObject(pid);if(h!=null&&h.optJSONObject("status")!=null&&h.getJSONObject("status").optBoolean("completed")&&!"error".equals(h.getJSONObject("status").optString("status_str")))collect(j,h);net.post(j,"/queue",new JSONObject().put("delete",new JSONArray().put(pid)));net.post(j,"/interrupt",new JSONObject().put("prompt_id",pid));JSONObject q=net.get(j,"/queue");if(!contains(q.optJSONArray("queue_running"),pid)&&!contains(q.optJSONArray("queue_pending"),pid)){j.remove("promptId");j.put("progress",JSONObject.NULL);task(j,"cancelled","已取消整个批次剩余任务");}else task(j,"cancelling","正在停止当前图片，后续任务已取消");}
}
